command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="5d7dc8c7a98b39ad3a6c80240d7d6f2f995bbfa9";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual docs FAST fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual docs FAST"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual docs candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-docs-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual docs worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual docs diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "network visual docs FAST failed"}
 Write-Host "NETWORK_VISUAL_DOCS_DIFF_CHECK=PASS"
 Write-Host "NETWORK_VISUAL_DOCS_FAST=PASS"
 Write-Host "NETWORK_VISUAL_REUSED_FINAL_RUN=37577442125"
 Write-Host "NETWORK_VISUAL_REUSED_FAST_RUN=37577331163"
 Write-Host "NETWORK_VISUAL_REUSED_BEFORE_RUN=37575384608"
 Write-Host "NETWORK_VISUAL_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
